std::vector<int> v1;              // Empty
std::vector<int> v2(10);          // Size 10, value initialized (0s)
std::vector<int> v3(5, 42);       // Size 5, value 42
std::vector<int> v4{1, 2, 3};     // Initializer list

std::vector<int> v_copy = v4;     // Copy
std::vector<int> v_move = std::move(v4); // Move

v1.push_back(5);                  // Add element (may reallocate)
v1.reserve(100);                  // Pre-allocate capacity

// Efficient insertion (avoids copy/move)
v2.emplace_back(99);

// Clear contents, capacity remains
v3.clear();

// Remove contents and reduce capacity to size (if capacity > size)
v2.shrink_to_fit();

// Swap trick for immediate capacity reduction (C++03/11)
std::vector<int>().swap(v1);

// Access (with bounds checking)
v2.at(0);
